<section class="chain-status <?= $chain['valid']?'valid':'invalid' ?>"><div><span class="success-mark"><?= $chain['valid']?'✓':'!' ?></span><div><strong><?= $chain['valid']?'Cadeia de auditoria íntegra':'Inconsistência detectada' ?></strong><span><?= $chain['valid']?'Todos os eventos encadeados foram verificados.':'Falha no evento #'.(int)($chain['event_id']??0) ?></span></div></div><code><?= $h(substr((string)($chain['last_hash']??''),0,24)) ?>…</code></section>
<section class="admin-panel"><div class="panel-heading"><div><span>Votos confirmados</span><h2>Análise antifraude</h2></div><a class="button secondary small" href="/admin/auditoria/exportar">Exportar log CSV</a></div><form class="filter-bar" method="get"><label>Status<select name="status"><option value="">Todos</option><?php foreach(['valid'=>'Válido','review'=>'Em revisão','invalid'=>'Inválido'] as $v=>$label): ?><option value="<?= $v ?>" <?= $filters['status']===$v?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Risco mínimo<input type="number" min="0" max="100" name="risk" value="<?= (int)$filters['risk'] ?>"></label><button class="button secondary small">Filtrar</button></form><div class="table-wrap"><table><thead><tr><th>Comprovante</th><th>Projeto</th><th>Sinais</th><th>Identificadores pseudônimos</th><th>Data</th><th>Revisão</th></tr></thead><tbody><?php foreach($votes as $vote): ?><tr><td><code><?= $h($vote['receipt_code']) ?></code><br><span class="status-pill <?= $h($vote['status']) ?>"><?= $h($vote['status']) ?></span></td><td><?= $h($vote['project_title']) ?><br><small><?= $h($vote['participant_name']) ?></small></td><td><span class="risk risk-<?= (int)$vote['risk_score']>=60?'high':((int)$vote['risk_score']>=30?'medium':'low') ?>"><?= (int)$vote['risk_score'] ?></span><br><small><?= $h(implode(', ',json_decode((string)$vote['risk_signals_json'],true)?:[])) ?></small></td><td><small>dispositivo <?= $h(substr((string)$vote['device_hash'],0,10)) ?>…<br>rede <?= $h(substr((string)$vote['ip_hash'],0,10)) ?>… · <?= $h($vote['country_code']) ?></small></td><td><?= $h(date('d/m/Y H:i',strtotime((string)$vote['confirmed_at']))) ?></td><td><form action="/admin/auditoria/voto" method="post" class="review-form"><input type="hidden" name="_csrf" value="<?= $h(Csrf::token()) ?>"><input type="hidden" name="id" value="<?= (int)$vote['id'] ?>"><select name="status"><option value="valid">Validar</option><option value="review" <?= $vote['status']==='review'?'selected':'' ?>>Manter em revisão</option><option value="invalid" <?= $vote['status']==='invalid'?'selected':'' ?>>Invalidar</option></select><input name="notes" placeholder="Nota da revisão"><button>Salvar</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
